const prevUnbindBoard = 'dom' in maybeState ? maybeState.dom.unbindBoard : undefined;
...
prevUnbindBoard?.();
const boardUnbind = events.bindBoard(state, onResize);
state.dom = { ..., unbindBoard: boardUnbind, ... };
